reference_patch.text:
diff --git a/block/ioprio.c b/block/ioprio.c
index 31666c92b46af29919f42ea3e1093caed7127d71..563435684c3c15aa87b4fe3b73813b205fa18275 100644
--- a/block/ioprio.c
+++ b/block/ioprio.c
@@ -149,8 +149,10 @@ static int get_task_ioprio(struct task_struct *p)
 	if (ret)
 		goto out;
 	ret = IOPRIO_PRIO_VALUE(IOPRIO_CLASS_NONE, IOPRIO_NORM);
+	task_lock(p);
 	if (p->io_context)
 		ret = p->io_context->ioprio;
+	task_unlock(p);
 out:
 	return ret;
 }

